void Solver::rephase() {
    // 1. Reset the rephase counter.
    rephases = 0;

    // 2. Make the trail‑size threshold a bit less aggressive.
    //    This postpones the next “local‑best” update slightly.
    threshold = static_cast<int>(threshold * 0.95);

    // 3. Grow the rephase limit adaptively (instead of a fixed +8192).
    //    The limit becomes larger as rephasing happens more often.
    rephase_limit = static_cast<int>(rephase_limit * 1.2) + 1024;

    // 4. Reset activity scaling to avoid overflow and give a fresh VSIDS start.
    var_inc = 1.0;
    for (int v = 1; v <= vars; ++v) {
        activity[v] = 1.0;
    }

    // 5. Rebuild the VSIDS heap with only currently unassigned variables.
    while (!vsids.empty()) vsids.pop();
    for (int v = 1; v <= vars; ++v) {
        if (value[v] == 0) {
            vsids.insert(v);
        }
    }

    // 6. Choose new saved phases:
    //    - 60 % keep the best local phase,
    //    - 20 % use the opposite of the best local phase,
    //    - 20 % pick a random polarity.
    int r = rand() % 100;
    if (r < 60) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 80) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }

    // 7. Backtrack to the root level so that the new phases take effect.
    backtrack(0);
}
